// codegen/src/emitter_program.cpp — runtime preludes and top-level function/program/plugin emission.

#include "emitter_internal.hpp"

namespace numkit::codegen {
namespace detail {

// The self-contained runtime prelude every emitted TU carries.
const char *kPrelude =
    "// Generated by numkit-codegen (RawBuffer ABI). Do not edit.\n"
    "#include <algorithm>\n"
    "#include <cmath>\n"
    "#include <complex>\n"
    "#include <cstddef>\n"
    "#include <cstdint>\n"
    "#include <cstdio>\n"
    "#include <initializer_list>\n"
    "#include <limits>\n"
    "#include <memory>\n"
    "#include <stdexcept>\n"
    "#include <vector>\n"
    "\n"
    "namespace numkit_rt {\n"
    "inline void disp(double x) { std::printf(\"    %.15g\\n\", x); }\n"
    "inline void disp(float x) { std::printf(\"    %.7g\\n\", static_cast<double>(x)); }\n"
    "inline void disp(bool b) { std::printf(\"   %d\\n\", b ? 1 : 0); }\n"
    "inline void disp(std::int8_t x) { std::printf(\"    %d\\n\", static_cast<int>(x)); }\n"
    "inline void disp(std::int16_t x) { std::printf(\"    %d\\n\", static_cast<int>(x)); }\n"
    "inline void disp(std::int32_t x) { std::printf(\"    %d\\n\", static_cast<int>(x)); }\n"
    "inline void disp(std::int64_t x) { std::printf(\"    %lld\\n\", static_cast<long long>(x)); }\n"
    "inline void disp(std::uint8_t x) { std::printf(\"    %u\\n\", static_cast<unsigned>(x)); }\n"
    "inline void disp(std::uint16_t x) { std::printf(\"    %u\\n\", static_cast<unsigned>(x)); }\n"
    "inline void disp(std::uint32_t x) { std::printf(\"    %u\\n\", static_cast<unsigned>(x)); }\n"
    "inline void disp(std::uint64_t x) { std::printf(\"    %llu\\n\", static_cast<unsigned long long>(x)); }\n"
    "inline void disp(std::complex<double> z) { std::printf(\"    %.15g %+.15gi\\n\", z.real(), z.imag()); }\n"
    "inline void disp(const char* s) { std::printf(\"%s\\n\", s); }\n"
    "template <class T>\n"
    "inline void disp_vec(const T* p, std::size_t n) {\n"
    "    for (std::size_t i = 0; i < n; ++i)\n"
    "        std::printf(\"%s%.15g\", i ? \"  \" : \"    \", static_cast<double>(p[i]));\n"
    "    std::printf(\"\\n\");\n"
    "}\n"
    "inline void disp_vec(const std::complex<double>* p, std::size_t n) {\n"
    "    for (std::size_t i = 0; i < n; ++i)\n"
    "        std::printf(\"%s%.15g%+.15gi\", i ? \"  \" : \"    \", p[i].real(), p[i].imag());\n"
    "    std::printf(\"\\n\");\n"
    "}\n"
    "inline void disp_vec(const std::uint16_t* p, std::size_t n) {\n"
    "    for (std::size_t i = 0; i < n; ++i)\n"
    "        std::putchar(static_cast<int>(p[i] & 0xFFu));\n"
    "    std::putchar('\\n');\n"
    "}\n"
    "template <class T>\n"
    "inline void disp_mat(const T* p, std::size_t rows, std::size_t cols) {\n"
    "    for (std::size_t r = 0; r < rows; ++r) {\n"
    "        for (std::size_t c = 0; c < cols; ++c)\n"
    "            std::printf(\"%s%.15g\", c ? \"  \" : \"    \", static_cast<double>(p[r + c * rows]));\n"
    "        std::printf(\"\\n\");\n"
    "    }\n"
    "}\n"
    "// Reference wrapper for a handle class: shared identity + lifetime; the\n"
    "// wrapped object stays a plain struct (no inheritance from shared_ptr).\n"
    "template <class T> class handle {\n"
    "    std::shared_ptr<T> p_;\n"
    "public:\n"
    "    handle() = default;\n"
    "    explicit handle(std::shared_ptr<T> p) : p_(static_cast<std::shared_ptr<T>&&>(p)) {}\n"
    "    T* operator->() const { return p_.get(); }\n"
    "    T& operator*()  const { return *p_; }\n"
    "    bool operator==(const handle& o) const { return p_ == o.p_; }\n"
    "    bool operator!=(const handle& o) const { return p_ != o.p_; }\n"
    "    bool isvalid() const { return static_cast<bool>(p_); }\n"
    "    template <class U> handle(const handle<U>& o) : p_(o.shared()) {}\n"
    "    const std::shared_ptr<T>& shared() const { return p_; }\n"
    "    template <class... A> static handle make(A&&... a)\n"
    "        { return handle(std::make_shared<T>(static_cast<A&&>(a)...)); }\n"
    "};\n"
    "// Convert a (double) array dimension to size_t. A negative dimension is a\n"
    "// hard error (the interpreter errors on negative dims too); the check\n"
    "// PRECEDES the cast so a negative value never reaches the float->unsigned\n"
    "// conversion (which would be UB). A fractional dim truncates toward zero, as\n"
    "// the interpreter does.\n"
    "inline std::size_t dim(double d) {\n"
    "    // Mirrors the interpreter's ops::toDim (reference parity, post fix/zeros-size-args):\n"
    "    // non-integer/non-finite -> error; a NEGATIVE dim clamps to 0 (zeros(-1,3) ->\n"
    "    // 0x3 empty); a size beyond size_t -> error. Guards PRECEDE the cast (a neg/\n"
    "    // non-finite/huge value would be UB to cast). Keeps codegen == the interpreter.\n"
    "    if (!std::isfinite(d) || d != std::floor(d))\n"
    "        throw std::runtime_error(\"Size inputs must be integers.\");\n"
    "    if (d < 0.0) return std::size_t{0};\n"
    "    if (d >= static_cast<double>(std::numeric_limits<std::size_t>::max()))\n"
    "        throw std::runtime_error(\"Requested array size is too large.\");\n"
    "    return static_cast<std::size_t>(d);\n"
    "}\n"
    "inline std::size_t check_idx1(double idx1, std::size_t bound, const char* msg) {\n"
    "    if (!std::isfinite(idx1) || idx1 < 1.0 || std::floor(idx1) != idx1\n"
    "        || idx1 >= static_cast<double>(std::numeric_limits<std::size_t>::max()))\n"
    "        throw std::out_of_range(msg);\n"
    "    const std::size_t i = static_cast<std::size_t>(idx1);\n"
    "    if (i > bound) throw std::out_of_range(msg);\n"
    "    return i - 1;\n"
    "}\n"
    "inline std::size_t check_idx1_grow(double idx1, const char* msg) {\n"
    "    if (!std::isfinite(idx1) || idx1 < 1.0 || std::floor(idx1) != idx1\n"
    "        || idx1 >= static_cast<double>(std::numeric_limits<std::size_t>::max()))\n"
    "        throw std::out_of_range(msg);\n"
    "    return static_cast<std::size_t>(idx1);\n"
    "}\n"
    "inline std::ptrdiff_t slice_bounds(double start, double step, double stop, std::size_t len,\n"
    "                                   std::ptrdiff_t& s0, std::ptrdiff_t& st) {\n"
    "    s0 = 0; st = 0;\n"
    "    if (!std::isfinite(start) || !std::isfinite(step) || !std::isfinite(stop))\n"
    "        throw std::out_of_range(\"numkit: index out of bounds\");\n"
    "    if (step == 0.0) return 0;\n"
    "    const double nr = (stop - start) / step;\n"
    "    if (nr < 0.0) return 0;\n"
    "    if (std::floor(start) != start || start < 1.0 || start > static_cast<double>(len))\n"
    "        throw std::out_of_range(\"numkit: index out of bounds\");\n"
    "    const double cnt_d = std::floor(nr + 1e-10) + 1.0;\n"
    "    if (cnt_d > 1.0 && std::floor(step) != step)\n"
    "        throw std::out_of_range(\"numkit: index out of bounds\");\n"
    "    const double last1 = start + (cnt_d - 1.0) * (cnt_d > 1.0 ? step : 0.0);\n"
    "    if (!std::isfinite(last1) || last1 < 1.0 || last1 > static_cast<double>(len)\n"
    "        || cnt_d > static_cast<double>(std::numeric_limits<std::ptrdiff_t>::max()))\n"
    "        throw std::out_of_range(\"numkit: index out of bounds\");\n"
    "    s0 = static_cast<std::ptrdiff_t>(start) - 1;\n"
    "    st = cnt_d > 1.0 ? static_cast<std::ptrdiff_t>(step) : 0;\n"
    "    return static_cast<std::ptrdiff_t>(cnt_d);\n"
    "}\n"
    "template <class T>\n"
    "inline T index(const T* a, std::size_t len, double idx1) {\n"
    "    return a[check_idx1(idx1, len, \"numkit: index out of bounds\")];\n"
    "}\n"
    "template <class T>\n"
    "inline void index_set(T* a, std::size_t len, double idx1, T v) {\n"
    "    a[check_idx1(idx1, len, \"numkit: index out of bounds (RawBuffer ABI cannot grow)\")] = v;\n"
    "}\n"
    "template <class T>\n"
    "inline void index_set_grow(std::vector<T>& v, double idx1, T val) {\n"
    "    const std::size_t i = check_idx1_grow(idx1, \"numkit: index out of bounds\");\n"
    "    if (i > v.size()) v.resize(i, T{});\n"
    "    v[i - 1] = val;\n"
    "}\n"
    "template <class T>\n"
    "inline T index2(const T* a, std::size_t rows, std::size_t cols, double i1, double j1) {\n"
    "    const std::size_t i0 = check_idx1(i1, rows, \"numkit: 2-D index out of bounds\");\n"
    "    const std::size_t j0 = check_idx1(j1, cols, \"numkit: 2-D index out of bounds\");\n"
    "    return a[j0 * rows + i0];\n"
    "}\n"
    "template <class T>\n"
    "inline void index2_set(T* a, std::size_t rows, std::size_t cols, double i1, double j1, T v) {\n"
    "    const std::size_t i0 = check_idx1(i1, rows, \"numkit: 2-D index out of bounds\");\n"
    "    const std::size_t j0 = check_idx1(j1, cols, \"numkit: 2-D index out of bounds\");\n"
    "    a[j0 * rows + i0] = v;\n"
    "}\n"
    "// N-D (rank>=3) column-major linear offset from 1-based subscripts + dims;\n"
    "// bounds-checked per axis. dims and subs are parallel (same rank).\n"
    "inline std::size_t nd_off(std::initializer_list<std::size_t> dims,\n"
    "                          std::initializer_list<double> subs) {\n"
    "    const std::size_t* d = dims.begin(); const double* s = subs.begin();\n"
    "    std::size_t off = 0, stride = 1;\n"
    "    for (std::size_t _numkit_a = 0; _numkit_a < dims.size(); ++_numkit_a) {\n"
    "        const std::size_t ik0 = check_idx1(s[_numkit_a], d[_numkit_a], \"numkit: N-D index out of bounds\");\n"
    "        off += ik0 * stride; stride *= d[_numkit_a];\n"
    "    }\n"
    "    return off;\n"
    "}\n"
    "template <class T>\n"
    "inline T indexN(const T* a, std::initializer_list<std::size_t> dims,\n"
    "                std::initializer_list<double> subs) { return a[nd_off(dims, subs)]; }\n"
    "template <class T>\n"
    "inline void indexN_set(T* a, std::initializer_list<std::size_t> dims,\n"
    "                       std::initializer_list<double> subs, T v) { a[nd_off(dims, subs)] = v; }\n"
    "} // namespace numkit_rt\n";

// The bridged-emission addendum (DESIGN.md §6a): the runtime C-ABI header +
// a tiny scalar-call helper. Appended ONLY when bridging is enabled, so a
// non-bridged TU stays self-contained / stdlib-only (the no-kludge litmus).
std::string bridgePrelude(const std::string &runtimeHeader)
{
    return "#include \"" + runtimeHeader + "\"\n"
           "#include <initializer_list>\n"
           "#include <complex>\n"
           "#include <vector>\n"
           "namespace numkit_rt {\n"
           "// Box scalar args, call the runtime, unbox a scalar result; leak-free,\n"
           "// errors propagate as a C++ exception (never across the C ABI).\n"
           "inline double bridge_scalar(const char* name, std::initializer_list<double> args) {\n"
           "    std::vector<numkit_val> argv; argv.reserve(args.size());\n"
           "    for (double x : args) argv.push_back(numkit_box_scalar(x));\n"
           "    numkit_error err; err.code = 0;\n"
           "    numkit_val r = numkit_call(name, argv.data(), argv.size(), 1, nullptr, &err);\n"
           "    for (numkit_val h : argv) numkit_release(h);\n"
           "    if (!r || err.code) { numkit_release(r);\n"
           "        throw std::runtime_error(err.code ? err.message : \"numkit bridged call failed\"); }\n"
           "    const double v = numkit_unbox_scalar(r); numkit_release(r); return v;\n"
           "}\n"
           "// Pre-boxed args (incl. arrays) -> call (1 output) -> unbox a SCALAR\n"
           "// result; releases args + result; errors throw. For array-arg\n"
           "// reductions (sum, prod, mean, max, min) whose arg can't be a scalar\n"
           "// C++ expression. Mirrors bridge_into but the result is a scalar.\n"
           "inline double bridge_scalar_arr(const char* name, numkit_val* args, std::size_t nargs) {\n"
           "    numkit_error err; err.code = 0;\n"
           "    numkit_val r = numkit_call(name, args, nargs, 1, nullptr, &err);\n"
           "    for (std::size_t i = 0; i < nargs; ++i) numkit_release(args[i]);\n"
           "    if (!r || err.code) { numkit_release(r);\n"
           "        throw std::runtime_error(err.code ? err.message : \"numkit bridged call failed\"); }\n"
           "    const double v = numkit_unbox_scalar(r); numkit_release(r); return v;\n"
           "}\n"
           "// Box-args -> call (1 output) -> unbox the array result into the\n"
           "// caller-allocated out buffer; releases args + result; errors throw.\n"
           "inline void bridge_into(const char* name, numkit_val* args, std::size_t nargs,\n"
           "                        double* out, std::size_t out_len) {\n"
           "    numkit_error err; err.code = 0;\n"
           "    numkit_val r = numkit_call(name, args, nargs, 1, nullptr, &err);\n"
           "    for (std::size_t i = 0; i < nargs; ++i) numkit_release(args[i]);\n"
           "    if (!r || err.code) { numkit_release(r);\n"
           "        throw std::runtime_error(err.code ? err.message : \"numkit bridged call failed\"); }\n"
           "    numkit_unbox_array(r, out, out_len); numkit_release(r);\n"
           "}\n"
           "// Same, but the result fills an owned vector (resized to its numel) —\n"
           "// for an array LOCAL whose size is only known at the call.\n"
           "inline void bridge_to_vec(const char* name, numkit_val* args, std::size_t nargs,\n"
           "                          std::vector<double>& out) {\n"
           "    numkit_error err; err.code = 0;\n"
           "    numkit_val r = numkit_call(name, args, nargs, 1, nullptr, &err);\n"
           "    for (std::size_t i = 0; i < nargs; ++i) numkit_release(args[i]);\n"
           "    if (!r || err.code) { numkit_release(r);\n"
           "        throw std::runtime_error(err.code ? err.message : \"numkit bridged call failed\"); }\n"
           "    out.resize(numkit_numel(r)); numkit_unbox_array(r, out.data(), out.size()); numkit_release(r);\n"
           "}\n"
           "// Char-result variant: unbox a CHAR array result into an owned uint16 vector (the\n"
           "// codegen's char width); the runtime owns the formatting (num2str/sprintf/...).\n"
           "inline void bridge_to_vec_char(const char* name, numkit_val* args, std::size_t nargs,\n"
           "                               std::vector<std::uint16_t>& out) {\n"
           "    numkit_error err; err.code = 0;\n"
           "    numkit_val r = numkit_call(name, args, nargs, 1, nullptr, &err);\n"
           "    for (std::size_t i = 0; i < nargs; ++i) numkit_release(args[i]);\n"
           "    if (!r || err.code) { numkit_release(r);\n"
           "        throw std::runtime_error(err.code ? err.message : \"numkit bridged call failed\"); }\n"
           "    out.resize(numkit_numel(r)); numkit_unbox_char_array(r, out.data(), out.size()); numkit_release(r);\n"
           "}\n"
           "// Complex-result variants: unbox a complex array result via the\n"
           "// interleaved-re,im C ABI (reinterpret the std::complex buffer).\n"
           "inline void bridge_into_cx(const char* name, numkit_val* args, std::size_t nargs,\n"
           "                           std::complex<double>* out, std::size_t out_len) {\n"
           "    numkit_error err; err.code = 0;\n"
           "    numkit_val r = numkit_call(name, args, nargs, 1, nullptr, &err);\n"
           "    for (std::size_t i = 0; i < nargs; ++i) numkit_release(args[i]);\n"
           "    if (!r || err.code) { numkit_release(r);\n"
           "        throw std::runtime_error(err.code ? err.message : \"numkit bridged call failed\"); }\n"
           "    numkit_unbox_complex_array(r, reinterpret_cast<double*>(out), out_len); numkit_release(r);\n"
           "}\n"
           "inline void bridge_to_vec_cx(const char* name, numkit_val* args, std::size_t nargs,\n"
           "                             std::vector<std::complex<double>>& out) {\n"
           "    numkit_error err; err.code = 0;\n"
           "    numkit_val r = numkit_call(name, args, nargs, 1, nullptr, &err);\n"
           "    for (std::size_t i = 0; i < nargs; ++i) numkit_release(args[i]);\n"
           "    if (!r || err.code) { numkit_release(r);\n"
           "        throw std::runtime_error(err.code ? err.message : \"numkit bridged call failed\"); }\n"
           "    out.resize(numkit_numel(r));\n"
           "    numkit_unbox_complex_array(r, reinterpret_cast<double*>(out.data()), out.size()); numkit_release(r);\n"
           "}\n"
           "// ---- Dynamic tier (DESIGN.md §10 C1) ----------------------------------\n"
           "// A value whose type the codegen could not infer: held BOXED as an owned\n"
           "// runtime handle (RAII), its operations dispatched to the runtime — the\n"
           "// universal sound fallback when no typed inline form exists. Copyable via\n"
           "// deep clone (nk value semantics); errors throw (never across the C ABI).\n"
           "class val {\n"
           "    numkit_val h_ = nullptr;\n"
           "public:\n"
           "    val() = default;\n"
           "    explicit val(numkit_val h) : h_(h) {}\n"
           "    ~val() { numkit_release(h_); }\n"
           "    val(const val& o) : h_(numkit_clone(o.h_)) {}\n"
           "    val(val&& o) noexcept : h_(o.h_) { o.h_ = nullptr; }\n"
           "    val& operator=(const val& o) {\n"
           "        if (this != &o) { numkit_val n = numkit_clone(o.h_); numkit_release(h_); h_ = n; } return *this; }\n"
           "    val& operator=(val&& o) noexcept {\n"
           "        if (this != &o) { numkit_release(h_); h_ = o.h_; o.h_ = nullptr; } return *this; }\n"
           "    numkit_val get() const { return h_; }\n"
           "    numkit_val take() { numkit_val h = h_; h_ = nullptr; return h; }  // release ownership out\n"
           "    static val scalar(double x) { return val(numkit_box_scalar(x)); }\n"
           "    static val array(const double* p, std::size_t n) { return val(numkit_box_array(p, n)); }\n"
           "    static val matrix(const double* p, std::size_t r, std::size_t c) {\n"
           "        return val(numkit_box_matrix(p, r, c)); }\n"
           "    static val array_nd(const double* p, std::initializer_list<std::size_t> dims) {\n"
           "        return val(numkit_box_array_nd(p, dims.begin(), (int)dims.size())); }\n"
           "    static val complex_array(const std::complex<double>* p, std::size_t n) {\n"
           "        return val(numkit_box_complex_array(reinterpret_cast<const double*>(p), n)); }\n"
           "    static val complex_matrix(const std::complex<double>* p, std::size_t r, std::size_t c) {\n"
           "        return val(numkit_box_complex_matrix(reinterpret_cast<const double*>(p), r, c)); }\n"
           "    static val complex_array_nd(const std::complex<double>* p, std::initializer_list<std::size_t> dims) {\n"
           "        return val(numkit_box_complex_array_nd(reinterpret_cast<const double*>(p), dims.begin(), (int)dims.size())); }\n"
           "    static val string(const char* s) { return val(numkit_box_string(s)); }\n"
           "    static val cell(std::initializer_list<val> elems) {\n"
           "        std::vector<numkit_val> ev; ev.reserve(elems.size());\n"
           "        for (const val& e : elems) ev.push_back(e.get());\n"
           "        return val(numkit_box_cell(ev.data(), ev.size())); }\n"
           "    static val cell_2d(std::initializer_list<val> elems, std::size_t rows,\n"
           "                       std::size_t cols) {  // elems ROW-MAJOR; stored column-major\n"
           "        std::vector<numkit_val> ev; ev.reserve(elems.size());\n"
           "        for (const val& e : elems) ev.push_back(e.get());\n"
           "        return val(numkit_box_cell_2d(ev.data(), rows, cols)); }\n"
           "    double to_scalar() const { return numkit_unbox_scalar(h_); }\n"
           "    bool truth() const {\n"
           "        numkit_error e; e.code = 0; int t = numkit_truth(h_, &e);\n"
           "        if (e.code) throw std::runtime_error(e.message); return t != 0; }\n"
           "};\n"
           "inline val _checked(numkit_val r, numkit_error& e) {\n"
           "    if (!r || e.code) { numkit_release(r);\n"
           "        throw std::runtime_error(e.code ? e.message : \"numkit dynamic op failed\"); }\n"
           "    return val(r); }\n"
           "inline val binop(const char* op, const val& a, const val& b) {\n"
           "    numkit_error e; e.code = 0; return _checked(numkit_binop(op, a.get(), b.get(), &e), e); }\n"
           "inline val unop(const char* op, const val& a) {\n"
           "    numkit_error e; e.code = 0; return _checked(numkit_unop(op, a.get(), &e), e); }\n"
           "// Box scalar args, call `name` (1 output), keep the result BOXED (the\n"
           "// Dynamic tier does not unbox an un-typeable result). Args released; throws.\n"
           "inline val call_dyn(const char* name, std::initializer_list<double> args) {\n"
           "    std::vector<numkit_val> argv; argv.reserve(args.size());\n"
           "    for (double x : args) argv.push_back(numkit_box_scalar(x));\n"
           "    numkit_error e; e.code = 0;\n"
           "    numkit_val r = numkit_call(name, argv.data(), argv.size(), 1, nullptr, &e);\n"
           "    for (numkit_val h : argv) numkit_release(h);\n"
           "    return _checked(r, e); }\n"
           "// Like call_dyn but the args are already boxed vals (a Dynamic / mixed\n"
           "// argument list, A3) — borrowed; their val owners release them. 1 output.\n"
           "inline val call_dynv(const char* name, std::initializer_list<val> args) {\n"
           "    std::vector<numkit_val> argv; argv.reserve(args.size());\n"
           "    for (const val& a : args) argv.push_back(a.get());\n"
           "    numkit_error e; e.code = 0;\n"
           "    numkit_val r = numkit_call(name, argv.data(), argv.size(), 1, nullptr, &e);\n"
           "    return _checked(r, e); }\n"
           "// Void-return bridged call (0 outputs, e.g. disp on a Dynamic/complex/ND value).\n"
           "inline void call_void(const char* name, std::initializer_list<val> args) {\n"
           "    std::vector<numkit_val> argv; argv.reserve(args.size());\n"
           "    for (const val& a : args) argv.push_back(a.get());\n"
           "    numkit_error e; e.code = 0;\n"
           "    numkit_val r = numkit_call(name, argv.data(), argv.size(), 0, nullptr, &e);\n"
           "    if (r) numkit_release(r);\n"
           "    if (e.code) throw std::runtime_error(e.message); }\n"
           "// Index a Dynamic value: a(subs) -> a new Dynamic value (A4). subs are\n"
           "// boxed vals (borrowed). The runtime resolves index-vs-call (a handle is\n"
           "// CALLED, an array is INDEXED) — sound whatever `a` is at runtime.\n"
           "inline val index_dyn(const val& a, std::initializer_list<val> subs) {\n"
           "    std::vector<numkit_val> sv; sv.reserve(subs.size());\n"
           "    for (const val& s : subs) sv.push_back(s.get());\n"
           "    numkit_error e; e.code = 0;\n"
           "    return _checked(numkit_index(a.get(), sv.data(), sv.size(), &e), e); }\n"
           "// Content extraction c{i} -> a new Dynamic value (G4). `idx1` is the\n"
           "// 1-based index as a double; the runtime applies the interpreter's\n"
           "// integer/range check. Throws on a non-cell / out-of-range index.\n"
           "inline val cell_get(const val& c, double idx1) {\n"
           "    numkit_error e; e.code = 0; return _checked(numkit_cell_get(c.get(), idx1, &e), e); }\n"
           "// 2-D content extraction c{i,j} -> a new Dynamic value (G4). 1-based\n"
           "// (row, col) subscripts as doubles. Throws on a non-cell / out-of-range.\n"
           "inline val cell_get_2d(const val& c, double i1, double j1) {\n"
           "    numkit_error e; e.code = 0; return _checked(numkit_cell_get_2d(c.get(), i1, j1, &e), e); }\n"
           "// Content store c{i} = v (G4). Mutates the cell in place, growing it if\n"
           "// `idx1` (1-based, double) is past the end. A fresh local (null handle) is\n"
           "// lazily made an empty cell first, so c{1}=v works without a prior c={}.\n"
           "inline void cell_set(val& c, double idx1, const val& v) {\n"
           "    if (!c.get()) c = val::cell({});\n"
           "    numkit_error e; e.code = 0; numkit_cell_set(c.get(), idx1, v.get(), &e);\n"
           "    if (e.code) throw std::runtime_error(e.message); }\n"
           "// 2-D content store c{i,j} = v (G4). Like cell_set but a (row, col)\n"
           "// subscript; grows to fit. A fresh local is lazily made an empty cell.\n"
           "inline void cell_set_2d(val& c, double i1, double j1, const val& v) {\n"
           "    if (!c.get()) c = val::cell({});\n"
           "    numkit_error e; e.code = 0; numkit_cell_set_2d(c.get(), i1, j1, v.get(), &e);\n"
           "    if (e.code) throw std::runtime_error(e.message); }\n"
           "// A named function handle @name (G5). Resolves in the runtime registry, so\n"
           "// the name is a builtin / engine function -- a co-compiled user spec is\n"
           "// refused at emit time. The result is a Dynamic value (called via index_dyn).\n"
           "inline val make_handle(const char* name) {\n"
           "    numkit_error e; e.code = 0; return _checked(numkit_make_handle(name, &e), e); }\n"
           "// A capture-free anonymous closure @(params)expr (G5b). The codegen proved\n"
           "// the body has no free variable that is an enclosing local / co-compiled fn,\n"
           "// so evaluating the (func2str-normalized) source yields the correct closure\n"
           "// -- the interpreter owns anon-fn semantics. `src` is the full @(...)... text.\n"
           "inline val make_closure(const char* src) {\n"
           "    numkit_error e; e.code = 0; return _checked(numkit_eval(src, &e), e); }\n"
           "// A CAPTURING anonymous closure @(...)... (G5c). Each captured local (names[i])\n"
           "// is boxed (vals[i]) and bound by value into the closure; the runtime evaluates\n"
           "// the source with those bindings so the closure snapshots them. names.size() ==\n"
           "// vals.size(). Throws on error.\n"
           "inline val make_closure_captured(const char* src,\n"
           "        std::initializer_list<const char*> names, std::initializer_list<val> vals) {\n"
           "    std::vector<const char*> nm(names);\n"
           "    std::vector<numkit_val> vv; vv.reserve(vals.size());\n"
           "    for (const val& v : vals) vv.push_back(v.get());\n"
           "    numkit_error e; e.code = 0;\n"
           "    return _checked(numkit_make_closure_captured(src, nm.data(), vv.data(), nm.size(), &e), e); }\n"
           "// Multi-output bridged call: `[o0, o1, ...] = name(args)`. Returns output\n"
           "// 0; outputs 1..nargout-1 are written (owned) into extra[0..nargout-2].\n"
           "// Args borrowed (their val owners release them). Errors throw.\n"
           "inline val call_dyn_multi(const char* name, std::initializer_list<val> args,\n"
           "                          std::size_t nargout, val* extra) {\n"
           "    std::vector<numkit_val> argv; argv.reserve(args.size());\n"
           "    for (const val& a : args) argv.push_back(a.get());\n"
           "    std::vector<numkit_val> ex(nargout > 1 ? nargout - 1 : 0, nullptr);\n"
           "    numkit_error e; e.code = 0;\n"
           "    numkit_val r = numkit_call(name, argv.data(), argv.size(), nargout, ex.data(), &e);\n"
           "    if (!r || e.code) { numkit_release(r); for (numkit_val h : ex) numkit_release(h);\n"
           "        throw std::runtime_error(e.code ? e.message : \"numkit dynamic op failed\"); }\n"
           "    for (std::size_t i = 0; i < ex.size(); ++i) extra[i] = val(ex[i]);\n"
           "    return val(r); }\n"
           "} // namespace numkit_rt\n";
}

// Emit ONE function (no prelude) under the RawBuffer ABI. `cppName`
// overrides the emitted symbol (for a mangled specialisation; empty -> the
// source name). `ctx` (when set) routes user-function calls and collects
// further specialisations. Returns {signature, definition}.
OneFn emitOneFunction(const ASTNode &funcDef, const std::vector<ParamSpec> &params,
                      const TransferRegistry &reg, ProgramEmitCtx *ctx,
                      const std::string &cppName, const ClassRegistry *classes,
                      const std::vector<ParamSpec> &extraSeed, bool bridge,
                      bool opsKernels, bool interprocByValueReturn)
{
    if (funcDef.type != NodeType::FUNCTION_DEF || funcDef.children.empty())
        unsupported("emitOneFunction expects a FUNCTION_DEF with a body");
    const std::size_t nout = funcDef.returnNames.size();

    const ASTNode &body = *funcDef.children[0];

    // The typing seed (entry) and the signature's parameters are distinct:
    // params drive the signature + the hoist-skip; `entry` is the typing
    // env (params PLUS extraSeed — pre-typed non-parameter locals such as a
    // constructor's output object, which are hoisted as locals, not params).
    TypeEnv                                     entry;
    std::unordered_map<std::string, ArrayInfo>  arrays;
    std::vector<std::string>                    sigParams;
    std::set<std::string>                       paramSet;
    std::vector<std::string> prologueStmts;
    std::vector<std::pair<std::string, std::string>> epilogueAssigns;
    for (const ParamSpec &p : params) {
        const std::string cpName = cppIdent(p.name);
        entry.set(p.name, {p.type, ConstVal::unknown()});
        paramSet.insert(p.name);
        if (isUnboxableScalarType(p.type)) {
            sigParams.push_back(cppScalarType(p.type.dtype) + " " + cpName);
        } else if (is2DMatrixType(p.type)) {
            // 2-D matrix -> pointer + dim companions (column-major).
            ArrayInfo ai;
            ai.dtype    = p.type.dtype;
            ai.is2D     = true;
            ai.rowsVar  = companion(p.name, "_rows");
            ai.colsVar  = companion(p.name, "_cols");
            ai.lenVar   = "(" + ai.rowsVar + " * " + ai.colsVar + ")";  // numel (elementwise)
            ai.dataExpr = cpName;
            arrays[p.name] = ai;
            sigParams.push_back("const " + cppArrayElemType(p.type.dtype) + "* " + cpName
                                + ", std::size_t " + ai.rowsVar + ", std::size_t " + ai.colsVar);
        } else if (p.type.isConcrete() && p.type.shape.isNDims()) {
            // N-D (rank>=3) param -> pointer + one size_t companion per dim
            // (column-major). Checked BEFORE isBufferArrayType, which also
            // matches an N-D shape. Companions carry the dims, so a runtime-dim
            // N-D param works too (the caller passes the sizes). Read-only.
            ArrayInfo ai;
            ai.dtype    = p.type.dtype;
            ai.isND     = true;
            ai.dataExpr = cpName;
            std::string sig = "const " + cppArrayElemType(p.type.dtype) + "* " + cpName;
            std::string prod;  // numel = product of the dim companions (elementwise)
            for (std::size_t d = 0; d < p.type.shape.nd.size(); ++d) {
                const std::string dv = companion(p.name, "_d" + std::to_string(d));
                ai.ndDims.push_back(dv);
                sig += ", std::size_t " + dv;
                prod += (prod.empty() ? "" : " * ") + dv;
            }
            ai.lenVar       = "(" + prod + ")";
            arrays[p.name] = ai;
            sigParams.push_back(sig);
        } else if (isBufferArrayType(p.type)) {
            ArrayInfo ai;
            ai.dtype       = p.type.dtype;
            ai.lenVar      = companion(p.name, "_len");
            ai.dataExpr    = cpName;
            ai.orient      = orientOf(p.type);
            arrays[p.name] = ai;
            sigParams.push_back("const " + cppArrayElemType(p.type.dtype) + "* " + cpName
                                + ", std::size_t " + ai.lenVar);
        } else if (p.type.isObject()) {
            // value class -> by value (value semantics); handle -> wrapper.
            sigParams.push_back(cppObjectType(p.type.classId, classes) + " " + cpName);
        } else if (p.type.isStruct()) {
            // A struct param explodes recursively into C++ params per leaf field, named
            // _numkit_fld_<p>_<f1>_<f2>... (the field-flatten convention the body reads).
            // The struct (and any nested sub-structs) are virtual -- no C++ param of their own.
            // Supports scalar, object, 1D/2D/ND array, and arbitrarily nested struct fields.
            if (!p.type.structLayout)
                unsupported("struct parameter '" + p.name + "' has no field layout");
            const bool isReturnStruct =
                std::find(funcDef.returnNames.begin(), funcDef.returnNames.end(), p.name)
                != funcDef.returnNames.end();
            std::function<void(const std::string &, const std::string &, const StructLayout &)>
                explodeStructParam = [&](const std::string &prefix,
                                         const std::string &dotPath,
                                         const StructLayout &layout) {
                    for (const auto &f : layout.fields) {
                        const std::string fld = prefix + "_" + f.first;
                        const std::string dp  = dotPath + "." + f.first;
                        const InferredType &ft = f.second;
                        entry.set(fld, {ft, ConstVal::unknown()});
                        if (ft.isStruct()) {
                            if (!ft.structLayout)
                                unsupported("nested struct parameter field '" + dp
                                            + "' has no field layout");
                            paramSet.insert(fld);
                            explodeStructParam(fld, dp, *ft.structLayout);
                        } else if (isUnboxableScalarType(ft)) {
                            paramSet.insert(fld);
                            sigParams.push_back(cppScalarType(ft.dtype) + " " + fld);
                        } else if (ft.isObject()) {
                            paramSet.insert(fld);
                            sigParams.push_back(cppObjectType(ft.classId, classes) + " " + fld);
                        } else if (is2DMatrixType(ft)) {
                            const std::string sigName = isReturnStruct ? ("_numkit_in_" + fld) : fld;
                            const std::string rowsVar = companion(sigName, "_rows");
                            const std::string colsVar = companion(sigName, "_cols");
                            const std::string lenExpr = "(" + rowsVar + " * " + colsVar + ")";
                            sigParams.push_back("const " + cppArrayElemType(ft.dtype) + "* " + sigName
                                                + ", std::size_t " + rowsVar
                                                + ", std::size_t " + colsVar);
                            if (isReturnStruct) {
                                prologueStmts.push_back(fld + ".assign(" + sigName + ", "
                                                        + sigName + " + " + lenExpr + ");");
                            } else {
                                ArrayInfo ai;
                                ai.dtype    = ft.dtype;
                                ai.is2D     = true;
                                ai.rowsVar  = rowsVar;
                                ai.colsVar  = colsVar;
                                ai.lenVar   = lenExpr;
                                ai.dataExpr = fld;
                                arrays[fld] = ai;
                                paramSet.insert(fld);
                            }
                        } else if (ft.isConcrete() && ft.shape.isNDims()) {
                            const std::string sigName = isReturnStruct ? ("_numkit_in_" + fld) : fld;
                            std::string sig = "const " + cppArrayElemType(ft.dtype) + "* " + sigName;
                            std::string prod;
                            std::vector<std::string> inDims;
                            for (std::size_t d = 0; d < ft.shape.nd.size(); ++d) {
                                const std::string dv = companion(sigName, "_d" + std::to_string(d));
                                inDims.push_back(dv);
                                sig += ", std::size_t " + dv;
                                prod += (prod.empty() ? "" : " * ") + dv;
                            }
                            const std::string lenExpr = "(" + prod + ")";
                            sigParams.push_back(sig);
                            if (isReturnStruct) {
                                prologueStmts.push_back(fld + ".assign(" + sigName + ", "
                                                        + sigName + " + " + lenExpr + ");");
                                bool allKnown = true;
                                for (std::size_t d : ft.shape.nd)
                                    if (d == 0) { allKnown = false; break; }
                                if (!allKnown) {
                                    for (std::size_t d = 0; d < ft.shape.nd.size(); ++d) {
                                        prologueStmts.push_back(
                                            companion(fld, "_d" + std::to_string(d)) + " = "
                                            + inDims[d] + ";");
                                    }
                                }
                            } else {
                                ArrayInfo ai;
                                ai.dtype    = ft.dtype;
                                ai.isND     = true;
                                ai.dataExpr = fld;
                                ai.ndDims   = inDims;
                                ai.lenVar   = lenExpr;
                                arrays[fld] = ai;
                                paramSet.insert(fld);
                            }
                        } else if (isBufferArrayType(ft)) {
                            const std::string sigName = isReturnStruct ? ("_numkit_in_" + fld) : fld;
                            const std::string lenVar  = companion(sigName, "_len");
                            sigParams.push_back("const " + cppArrayElemType(ft.dtype) + "* " + sigName
                                                + ", std::size_t " + lenVar);
                            if (isReturnStruct) {
                                prologueStmts.push_back(fld + ".assign(" + sigName + ", "
                                                        + sigName + " + " + lenVar + ");");
                            } else {
                                ArrayInfo ai;
                                ai.dtype    = ft.dtype;
                                ai.lenVar   = lenVar;
                                ai.dataExpr = fld;
                                ai.orient   = orientOf(ft);
                                arrays[fld] = ai;
                                paramSet.insert(fld);
                            }
                        } else {
                            unsupported("struct parameter field '" + dp + "' has unsupported type "
                                        + ft.str());
                        }
                    }
                };
            explodeStructParam("_numkit_fld_" + p.name, p.name, *p.type.structLayout);
        } else if (bridge && p.type.isDynamic()) {
            // Dynamic tier (DESIGN.md §10 C1): an un-typeable parameter is a boxed
            // numkit_rt::val passed BY VALUE — pass-by-value is a copy (val's
            // copy = deep clone). Directly usable as a Dynamic local in the body.
            sigParams.push_back("numkit_rt::val " + cpName);
        } else {
            unsupported("parameter '" + p.name + "' has an unsupported type for RawBuffer ABI");
        }
    }
    for (const ParamSpec &es : extraSeed)  // pre-typed locals (e.g. ctor output)
        entry.set(es.name, {es.type, ConstVal::unknown()});

    DeclTypeMap decls = computeDeclTypes(body, entry, reg, classes);

    // Reserved-identifier guard. A user variable / parameter is emitted VERBATIM
    // as a C++ name (synthesised names escape "__", but user names stay readable
    // as-is). "__" anywhere in an identifier is reserved to the implementation
    // ([lex.name]) — UB to declare. A leading "_"+uppercase is impossible (an
    // identifier cannot begin with "_"), so "__" is the only reserved
    // shape a user name can take. Refuse it with a clear message rather than
    // emit UB. (A function/method NAME may contain "__"; it is mangled through
    // escapeBase, so it never reaches the output verbatim — only var names do.)
    {
        auto refuseDunder = [](const std::string &name) {
            if (name.find("__") != std::string::npos)
                unsupported("identifier '" + name + "' contains '__', which is reserved in C++ "
                            "([lex.name]) — rename the variable");
        };
        for (const std::string &p : paramSet) refuseDunder(p);
        for (const auto &[n, t] : decls) refuseDunder(n);
    }

    // Rank-unknown (`ShapeKind::Unknown`) non-parameter locals arise when branches merge
    // incompatible shapes (e.g. 2x3 and 4x5). Under `bridge`, hoist them in the Dynamic tier
    // (`numkit_rt::val`) so runtime rank/dimensions are preserved faithfully; without `bridge`,
    // they fall through to the explicit RawBuffer refusal below instead of miscompiling as 1-D.
    if (bridge) {
        for (auto &[n, t] : decls) {
            if (paramSet.count(n)) continue;
            if (t.isConcrete() && t.shape.kind == ShapeKind::Unknown)
                t = InferredType::dynamic();
        }
    }

    // Helper: register a `std::vector<T>&` out-param for an array (struct output field
    // or non-leading multi-output array). Treated like a local vector (`ai.isLocal = true`)
    // for `.resize()` / `.assign()` / `.data()` / `.size()`, with `ai.isRefParam = true`
    // so `hoistArrayLocals()` does not redeclare the vector inside the body.
    auto registerOutRefArray = [&](const std::string &varName, const InferredType &ft) {
        const std::string cVar = cppIdent(varName);
        if (is2DMatrixType(ft)) {
            ArrayInfo ai;
            ai.dtype      = ft.dtype;
            ai.isLocal    = true;
            ai.isRefParam = true;
            ai.is2D       = true;
            ai.dataExpr   = cVar + ".data()";
            ai.lenVar     = cVar + ".size()";
            ai.rowsVar    = std::to_string(ft.shape.rows);
            ai.colsVar    = std::to_string(ft.shape.cols);
            arrays[varName] = ai;
        } else if (ft.isConcrete() && ft.shape.isNDims()) {
            ArrayInfo ai;
            ai.dtype      = ft.dtype;
            ai.isLocal    = true;
            ai.isRefParam = true;
            ai.isND       = true;
            ai.dataExpr   = cVar + ".data()";
            ai.lenVar     = cVar + ".size()";
            bool allKnown = true;
            for (std::size_t d : ft.shape.nd)
                if (d == 0) { allKnown = false; break; }
            if (allKnown) {
                for (std::size_t d : ft.shape.nd) ai.ndDims.push_back(std::to_string(d));
            } else {
                ai.ndRuntimeLocal = true;
                for (std::size_t d = 0; d < ft.shape.nd.size(); ++d)
                    ai.ndDims.push_back(companion(varName, "_d" + std::to_string(d)));
            }
            arrays[varName] = ai;
        } else {
            ArrayInfo ai;
            ai.dtype      = ft.dtype;
            ai.isLocal    = true;
            ai.isRefParam = true;
            ai.dataExpr   = cVar + ".data()";
            ai.lenVar     = cVar + ".size()";
            ai.orient     = orientOf(ft);
            arrays[varName] = ai;
        }
        paramSet.insert(varName);
        sigParams.push_back("std::vector<" + cppArrayElemType(ft.dtype) + ">& " + cVar);
    };

    // Helper: recursively explode a struct output into per-leaf reference out-params.
    std::function<void(const std::string &, const std::string &, const StructLayout &)>
        explodeStructOutput = [&](const std::string &prefix,
                                  const std::string &dotPath,
                                  const StructLayout &layout) {
            for (const auto &f : layout.fields) {
                const std::string fld = prefix + "_" + f.first;
                const std::string dp  = dotPath + "." + f.first;
                const InferredType &ft = f.second;
                entry.set(fld, {ft, ConstVal::unknown()});
                if (ft.isStruct()) {
                    if (!ft.structLayout)
                        unsupported("nested struct output field '" + dp + "' has no field layout");
                    paramSet.insert(fld);
                    explodeStructOutput(fld, dp, *ft.structLayout);
                } else if (isUnboxableScalarType(ft)) {
                    if (paramSet.count(fld)) {
                        const std::string outRef = "_numkit_out_" + fld;
                        sigParams.push_back(cppScalarType(ft.dtype) + "& " + outRef);
                        epilogueAssigns.push_back({outRef, fld});
                    } else {
                        paramSet.insert(fld);
                        sigParams.push_back(cppScalarType(ft.dtype) + "& " + fld);
                    }
                } else if (ft.isObject()) {
                    if (paramSet.count(fld)) {
                        const std::string outRef = "_numkit_out_" + fld;
                        sigParams.push_back(cppObjectType(ft.classId, classes) + "& " + outRef);
                        epilogueAssigns.push_back({outRef, fld});
                    } else {
                        paramSet.insert(fld);
                        sigParams.push_back(cppObjectType(ft.classId, classes) + "& " + fld);
                    }
                } else if (is2DMatrixType(ft) || (ft.isConcrete() && ft.shape.isNDims())
                           || isBufferArrayType(ft)) {
                    registerOutRefArray(fld, ft);
                } else {
                    unsupported("struct output field '" + dp + "' has unsupported type " + ft.str());
                }
            }
        };

    // Return classification:
    //   0 outputs -> void (e.g. a handle class's in-place mutator);
    //   1 output  -> scalar (by value) / array (out-param) / object (by value) / struct (out-params);
    //   N outputs -> void (or leading by-value array) + reference out-params per output.
    std::string retCpp             = "void";
    std::string retName;
    bool        arrayReturn        = false;
    bool        dynamicReturn      = false;
    bool        multiByValueReturn = false;  // nout>=2 + leading array (output 0 by value)
    if (nout == 1) {
        retName                  = funcDef.returnNames[0];
        const std::string cRet   = cppIdent(retName);
        const auto        retIt  = decls.find(retName);
        if (retIt == decls.end())
            unsupported("output '" + retName + "' is never assigned");
        const InferredType retType = retIt->second;
        if (isUnboxableScalarType(retType)) {
            retCpp = cppScalarType(retType.dtype);
        } else if (interprocByValueReturn && isByValueReturnArrayType(retType)) {
            retCpp = "std::vector<" + cppArrayElemType(retType.dtype) + ">";
        } else if (retType.isConcrete() && retType.shape.isNDims()) {
            arrayReturn = true;
            retCpp      = "void";
            ArrayInfo ai;
            ai.dtype    = retType.dtype;
            ai.isND     = true;
            ai.isOutput = true;
            ai.dataExpr = cRet;
            std::string sig  = cppArrayElemType(retType.dtype) + "* __restrict " + cRet;
            std::string prod;  // total length = product of the companions
            for (std::size_t d = 0; d < retType.shape.nd.size(); ++d) {
                const std::string dv = companion(retName, "_d" + std::to_string(d));
                ai.ndDims.push_back(dv);
                sig  += ", std::size_t " + dv;
                prod += (prod.empty() ? "" : " * ") + dv;
            }
            ai.lenVar       = "(" + prod + ")";  // drives the zeros/ones fill loop
            arrays[retName] = ai;
            sigParams.push_back(sig);
        } else if (is2DMatrixType(retType)) {
            arrayReturn = true;
            retCpp      = "void";
            ArrayInfo ai;
            ai.dtype    = retType.dtype;
            ai.is2D     = true;
            ai.isOutput = true;
            ai.dataExpr = cRet;
            ai.rowsVar  = companion(retName, "_rows");
            ai.colsVar  = companion(retName, "_cols");
            ai.lenVar   = "(" + ai.rowsVar + " * " + ai.colsVar + ")";  // zeros/ones fill bound
            arrays[retName] = ai;
            sigParams.push_back(cppArrayElemType(retType.dtype) + "* __restrict " + cRet
                                + ", std::size_t " + ai.rowsVar + ", std::size_t " + ai.colsVar);
        } else if (isBufferArrayType(retType)) {
            arrayReturn = true;
            retCpp      = "void";
            ArrayInfo ai;
            ai.dtype        = retType.dtype;
            ai.lenVar       = companion(retName, "_len");
            ai.isOutput     = true;
            ai.dataExpr     = cRet;
            ai.orient       = orientOf(retType);
            arrays[retName] = ai;
            sigParams.push_back(cppArrayElemType(retType.dtype) + "* __restrict " + cRet
                                + ", std::size_t " + ai.lenVar);
        } else if (retType.isObject()) {
            // returned BY VALUE (value class) / handle wrapper — not an
            // out-param; the scalar-return path (return retName;) applies.
            retCpp = cppObjectType(retType.classId, classes);
        } else if (retType.isStruct()) {
            if (!retType.structLayout)
                unsupported("struct output '" + retName + "' has no field layout");
            arrayReturn = true;  // void; body fills the out-params; no scalar return emitted
            retCpp      = "void";
            explodeStructOutput("_numkit_fld_" + retName, retName, *retType.structLayout);
        } else if (bridge
                   && (retType.isDynamic()
                       || (retType.isConcrete() && retType.shape.kind == ShapeKind::Unknown))) {
            retCpp        = "numkit_val";
            dynamicReturn = true;
        } else {
            unsupported("output '" + retName + "' has an unsupported type");
        }
    } else if (nout >= 2) {
        for (std::size_t oi = 0; oi < funcDef.returnNames.size(); ++oi) {
            const std::string &rn  = funcDef.returnNames[oi];
            const std::string  cRn = cppIdent(rn);
            if (rn.empty()) unsupported("multi-output with an unnamed output");
            const auto         it = decls.find(rn);
            const InferredType t  = (it != decls.end()) ? it->second : InferredType::dynamic();
            if (oi == 0 && isByValueReturnArrayType(t)) {
                retCpp             = "std::vector<" + cppArrayElemType(t.dtype) + ">";
                retName            = rn;
                multiByValueReturn = true;
                continue;
            }
            if (t.isStruct()) {
                if (!t.structLayout)
                    unsupported("struct multi-output '" + rn + "' has no field layout");
                explodeStructOutput("_numkit_fld_" + rn, rn, *t.structLayout);
                continue;
            }
            if (is2DMatrixType(t) || (t.isConcrete() && t.shape.isNDims())
                || isBufferArrayType(t)) {
                registerOutRefArray(rn, t);
                continue;
            }
            if (t.isObject()) {
                if (paramSet.count(rn)) {
                    const std::string outRef = "_numkit_out_" + rn;
                    sigParams.push_back(cppObjectType(t.classId, classes) + "& " + outRef);
                    epilogueAssigns.push_back({outRef, cRn});
                } else {
                    sigParams.push_back(cppObjectType(t.classId, classes) + "& " + cRn);
                    paramSet.insert(rn);
                }
                continue;
            }
            if (!isUnboxableScalarType(t))
                unsupported("multi-output '" + rn + "' has unsupported type " + t.str());
            if (paramSet.count(rn)) {
                const std::string outRef = "_numkit_out_" + rn;
                sigParams.push_back(cppScalarType(t.dtype) + "& " + outRef);
                epilogueAssigns.push_back({outRef, cRn});
            } else {
                sigParams.push_back(cppScalarType(t.dtype) + "& " + cRn);
                paramSet.insert(rn);  // a reference param, not a hoisted local
            }
        }
    }

    // Array LOCALS: a 1-D buffer-array-typed variable that is neither a
    // parameter nor the output is an owned, runtime-sized std::vector. Register
    // it so index / numel / call-arg resolve to `<name>.data()` / `.size()`.
    for (const auto &[name, t] : decls) {
        if (paramSet.count(name) || arrays.count(name)) continue;  // params + the output
        const std::string cName = cppIdent(name);
        if (is2DMatrixType(t)) {
            ArrayInfo ai;
            ai.dtype     = t.dtype;
            ai.isLocal   = true;
            ai.is2D      = true;
            ai.dataExpr  = cName + ".data()";
            ai.lenVar    = cName + ".size()";
            ai.rowsVar   = std::to_string(t.shape.rows);
            ai.colsVar   = std::to_string(t.shape.cols);
            arrays[name] = ai;
        } else if (t.isConcrete() && t.shape.isNDims()) {
            ArrayInfo ai;
            ai.dtype    = t.dtype;
            ai.isLocal  = true;
            ai.isND     = true;
            ai.dataExpr = cName + ".data()";
            ai.lenVar   = cName + ".size()";
            bool allKnown = true;
            for (std::size_t d : t.shape.nd)
                if (d == 0) { allKnown = false; break; }
            if (allKnown) {
                for (std::size_t d : t.shape.nd) ai.ndDims.push_back(std::to_string(d));
            } else {
                ai.ndRuntimeLocal = true;
                for (std::size_t d = 0; d < t.shape.nd.size(); ++d)
                    ai.ndDims.push_back(companion(name, "_d" + std::to_string(d)));
            }
            arrays[name] = ai;
        } else if (isBufferArrayType(t)) {
            ArrayInfo ai;
            ai.dtype     = t.dtype;
            ai.isLocal   = true;
            ai.dataExpr  = cName + ".data()";
            ai.lenVar    = cName + ".size()";
            ai.orient    = orientOf(t);
            arrays[name] = ai;
        }
    }

    const std::string symbol = cppName.empty() ? cppGlobalIdent(funcDef.strValue) : cppName;
    std::string       sig    = retCpp + " " + symbol + "(";
    for (std::size_t i = 0; i < sigParams.size(); ++i)
        sig += (i ? ", " : "") + sigParams[i];
    sig += ")";

    // Optimisation facts (brick 6). Empty facts => the always-correct
    // checked form; the analysis only enables faster lowering.
    const OptFacts opt = analyzeOptimizations(body, arrays);
    std::set<std::string> promotedVars;  // their counter is declared in the for, not hoisted
    for (const ASTNode *f : opt.promotedLoops) promotedVars.insert(f->strValue);

    // Emit hoisted local declarations (deterministic order) + the body.
    Emitter em(entry, reg, arrays, opt, ctx, classes, bridge, opsKernels);
    em.hoistArrayLocals();  // owned-vector array locals first
    std::map<std::string, InferredType> ordered(decls.begin(), decls.end());
    for (const auto &[name, t] : ordered) {
        if (paramSet.count(name) || arrays.count(name) || promotedVars.count(name))
            continue;  // signature params / arrays / promoted loop counters
        if (t.isStruct())
            continue;  // a plain struct is VIRTUAL: no storage of its own -- its fields are
                       // the _numkit_fld_* locals, hoisted separately (G2 field-flattening).
        // A Dynamic local is allowed under bridging — it lives in the Dynamic
        // tier as a boxed numkit_rt::val (DESIGN.md §10 C1). Without bridging there
        // is no runtime to hold it, so it stays the explicit refusal.
        const bool isBoxedDynamic =
            t.isDynamic() || (t.isConcrete() && t.shape.kind == ShapeKind::Unknown);
        if (!isUnboxableScalarType(t) && !t.isObject() && !(bridge && isBoxedDynamic))
            unsupported("local '" + name + "' is not an unboxable scalar or object (type "
                        + t.str() + ") — unsupported in RawBuffer ABI");
        em.hoistLocal(name, isBoxedDynamic ? InferredType::dynamic() : t);
        if (bridge && isBoxedDynamic) em.addDynamicLocal(name);  // boxed-assign discipline
    }
    for (const std::string &ps : prologueStmts) em.emitRawLine(ps);
    em.setReturnInfo(multiByValueReturn || (nout == 1 && !arrayReturn), retName, dynamicReturn);
    em.setEpilogueAssigns(epilogueAssigns);
    em.emitStmt(body);
    // Trailing return for the fall-through path. Skipped when the body already
    // ends in an explicit `return` (its emitStmt emitted the return), so we don't
    // emit a dead duplicate; a CONDITIONAL early return leaves the trailing return
    // reachable, so it stays.
    const bool bodyEndsInReturn = body.type == NodeType::BLOCK && !body.children.empty()
                                  && body.children.back()
                                  && body.children.back()->type == NodeType::RETURN_STMT;
    if (!bodyEndsInReturn) {
        em.emitEpilogueAssigns();
        if (multiByValueReturn || (nout == 1 && !arrayReturn))
            dynamicReturn ? em.emitReturnDynamic(retName) : em.emitReturnScalar(retName);
    }

    std::string definition = sig + " {\n";
    definition += em.out();
    definition += "}\n";
    return {sig, definition};
}

} // namespace detail

using namespace detail;

// Emit the C++ struct for every class in `classes` (empty when null).
static std::string emitAllStructs(const ClassRegistry *classes)
{
    std::string s;
    if (classes)
        for (std::size_t i = 0; i < classes->size(); ++i)
            s += emitClassStruct(*classes->byId(static_cast<int>(i)));
    return s;
}

// ── whole-function emission (3f) ──────────────────────────────────────
EmittedFunction emitFunction(const ASTNode &funcDef,
                             const std::vector<ParamSpec> &params,
                             const TransferRegistry &reg, const ClassRegistry *classes,
                             const BridgeOptions &bridge, const OpsKernelOptions &opsKernels)
{
    const OneFn f = emitOneFunction(funcDef, params, reg, /*ctx=*/nullptr, /*cppName=*/"", classes,
                                    /*extraSeed=*/{}, bridge.enabled, opsKernels.enabled);
    std::string source = kPrelude;
    source += "\n";
    if (opsKernels.enabled) source += "#include <numkit/ops/kernels.hpp>\n";
    if (bridge.enabled) source += bridgePrelude(bridge.runtimeHeader);
    source += emitAllStructs(classes);
    source += f.definition;
    return {source, cppGlobalIdent(funcDef.strValue), f.signature};
}

// ── whole-program emission (§12 brick 1b) ─────────────────────────────
EmittedFunction emitProgram(const ASTNode &entryDef,
                            const std::vector<ParamSpec> &params,
                            const FunctionTable &table, const TransferRegistry &reg,
                            const ClassRegistry *classes, const BridgeOptions &bridge,
                            const OpsKernelOptions &opsKernels)
{
    ProgramEmitCtx ctx;
    ctx.funcs = &table;

    std::vector<InferredType> entryArgTypes;
    entryArgTypes.reserve(params.size());
    for (const auto &p : params) entryArgTypes.push_back(p.type);
    const std::string entryMangled = mangle(entryDef.strValue, entryArgTypes);
    ctx.seen.insert(entryMangled);

    std::vector<std::string> sigs, defs;
    const OneFn ef = emitOneFunction(entryDef, params, reg, &ctx, entryMangled, classes, {},
                                     bridge.enabled, opsKernels.enabled);
    const std::string entrySig = ef.signature;
    sigs.push_back(ef.signature);
    defs.push_back(ef.definition);

    // Drain the worklist: each specialisation may discover more calls.
    while (!ctx.pending.empty()) {
        const CallSite cs = ctx.pending.back();
        ctx.pending.pop_back();
        if (cs.argTypes.size() != cs.def->paramNames.size())
            unsupported("arity mismatch emitting '" + cs.def->strValue + "'");
        std::vector<ParamSpec> ps;
        ps.reserve(cs.argTypes.size());
        for (std::size_t i = 0; i < cs.argTypes.size(); ++i)
            ps.push_back({cs.def->paramNames[i], cs.argTypes[i]});
        const OneFn cf = emitOneFunction(*cs.def, ps, reg, &ctx, cs.mangled, classes, cs.extraSeed,
                                         bridge.enabled, opsKernels.enabled,
                                         /*interprocByValueReturn=*/true);
        sigs.push_back(cf.signature);
        defs.push_back(cf.definition);
    }

    std::string source = kPrelude;
    source += "\n";
    if (opsKernels.enabled) source += "#include <numkit/ops/kernels.hpp>\n";
    if (bridge.enabled) source += bridgePrelude(bridge.runtimeHeader);
    source += emitAllStructs(classes);              // class structs precede all functions
    source += "\n";
    for (const auto &s : sigs) source += s + ";\n";  // forward declarations
    source += "\n";
    for (const auto &d : defs) source += d;
    return {source, entryMangled, entrySig};
}

// ── codegen-as-plugin (tiered acceleration, §6b) ──────────────────────
std::string emitScalarPlugin(const ASTNode &funcDef,
                             const std::vector<ParamSpec> &params,
                             const TransferRegistry &reg, const std::string &exportName,
                             const std::string &abiHeaderPath, const ClassRegistry *classes)
{
    // Preconditions (the sound boundary): a SCALAR single output (the
    // output-size protocol for an array result is a later layer), and each
    // parameter is a scalar OR a double row vector. inferFunctionReturn yields
    // Dynamic for a multi-output / untypeable function, so the
    // isUnboxableScalar() return check covers those too.
    std::vector<ArgInfo> args;
    args.reserve(params.size());
    for (const auto &p : params) {
        const bool scalar   = p.type.isUnboxableScalar();
        const bool dblVector = isBufferArrayType(p.type) && p.type.dtype == ValueType::DOUBLE;
        if (!scalar && !dblVector)
            unsupported("plugin export: parameter '" + p.name
                        + "' must be a scalar or a double vector (v1)");
        args.push_back(ArgInfo::of(p.type));
    }
    const InferredType ret = inferFunctionReturn(funcDef, args, reg, classes);
    if (!ret.isUnboxableScalar())
        unsupported("plugin export: '" + funcDef.strValue
                    + "' must have a single SCALAR output (v1; array output needs the "
                      "size protocol)");

    // The compiled function (throws if its body is outside the subset).
    const EmittedFunction ef = emitFunction(funcDef, params, reg, classes);
    const std::size_t     n  = params.size();

    // Per-parameter marshalling: a scalar unboxes inline; a double vector
    // unboxes into a buffer (sized by the runtime value) passed as ptr+len.
    std::string preDecls, callArgs;
    for (std::size_t i = 0; i < n; ++i) {
        const std::string ix = std::to_string(i);
        if (i) callArgs += ", ";
        if (params[i].type.isUnboxableScalar()) {
            callArgs += "static_cast<" + cppScalarType(params[i].type.dtype)
                        + ">(numkit__host->unbox_scalar(a[" + ix + "]))";
        } else {  // double vector
            const std::string b = "__b" + ix;
            preDecls += "    std::vector<double> " + b + "(numkit__host->numel(a[" + ix + "]));\n";
            preDecls += "    numkit__host->unbox_array(a[" + ix + "], " + b + ".data(), " + b
                        + ".size());\n";
            callArgs += b + ".data(), " + b + ".size()";
        }
    }

    std::string s = ef.source;
    s += "\n#include \"" + abiHeaderPath + "\"\n";
    s += "#include <cstdio>\n";
    s += "#include <vector>\n";
    s += "namespace {\n";
    s += "const numkit_host_api *numkit__host = nullptr;\n";
    s += "numkit_val numkit__wrap(const numkit_val *a, size_t nargs, size_t nargout,\n";
    s += "                numkit_val *extra_outs, numkit_error *err) {\n";
    s += "    (void)nargout; (void)extra_outs;\n";
    s += "    if (nargs < " + std::to_string(n) + ") {\n";
    s += "        if (err) { err->code = 1; std::snprintf(err->message, sizeof(err->message),\n";
    s += "            \"" + exportName + ": expected " + std::to_string(n) + " argument(s)\"); }\n";
    s += "        return nullptr;\n";
    s += "    }\n";
    s += preDecls;
    s += "    return numkit__host->box_scalar(static_cast<double>(" + ef.name + "(" + callArgs + ")));\n";
    s += "}\n";
    s += "}  // namespace\n";
    s += "extern \"C\" {\n";
    s += "NUMKIT_PLUGIN_EXPORT int numkit_plugin_abi_version(void) { return NUMKIT_PLUGIN_ABI_VERSION; }\n";
    s += "NUMKIT_PLUGIN_EXPORT int numkit_plugin_register(const numkit_host_api *host) {\n";
    s += "    numkit__host = host;\n";
    s += "    return host->register_fn(\"" + exportName + "\", &numkit__wrap);\n";
    s += "}\n";
    s += "}  // extern \"C\"\n";
    return s;
}

// ── class struct emission (§12 brick 5) ───────────────────────────────
std::string emitClassStruct(const ClassInfo &ci)
{
    std::string s = "struct " + cppGlobalIdent(ci.name) + " {\n";
    for (const auto &f : ci.fields) {
        if (!f.type.isUnboxableScalar())
            unsupported("class '" + ci.name + "' field '" + f.name
                        + "' is not an unboxed scalar (v1)");
        const std::string init =
            f.defaultExpr ? emitScalarExpr(*f.defaultExpr) : zeroLiteral(f.type.dtype);
        s += "    " + cppScalarType(f.type.dtype) + " " + cppIdent(f.name) + " = " + init + ";\n";
    }
    s += "};\n";
    return s;
}


} // namespace numkit::codegen
